fn is_non_prime(n: u64) -> bool {
    // Precondition: n must be at least 2
    // Requires: n >= 2
    // Ensures: The return value is true if n is non-prime, false otherwise
    // Decreases: n (in the context of the loop)
    // Invariant: For all k in the range 3..=limit, if n % k == 0, then n is non-prime
    //            and limit is the integer part of the square root of n.
    //            Also, if n is even and greater than 2, then n is non-prime.
    //            If n is prime, then no divisors will be found in the loop.
    //            The function will return false in that case.
    assert!(n >= 2); // Safety check, should not fail in valid usage

    if n < 2 {
        return false; // n is guaranteed to be at least 2, so this is just a safety check.
    }
    if n == 2 {
        return false; // 2 is prime
    }
    if n % 2 == 0 {
        return true; // Any even number greater than 2 is non-prime
    }
    
    // Check for odd divisors from 3 to the square root of n
    let limit = (n as f64).sqrt() as u64;
    // Invariant: 3 <= k <= limit
    for k in (3..=limit).step_by(2) {
        // Invariant: n % k == 0 implies n is non-prime
        if n % k == 0 {
            return true; // Found a non-trivial divisor
        }
    }
    
    false // No divisors found, n is prime
}

